package vn.svframe.svframemmo.skill.list;
import org.joml.Vector3f;import net.minecraft.entity.LivingEntity;import net.minecraft.particle.DustParticleEffect;import net.minecraft.particle.ParticleTypes;import net.minecraft.server.network.ServerPlayerEntity;import net.minecraft.server.world.ServerWorld;import net.minecraft.sound.SoundCategory;import net.minecraft.sound.SoundEvents;import net.minecraft.util.math.Vec3d;import vn.svframe.svframelib.SVFrameLib;import vn.svframe.svframelib.api.event.PlayerAttackEvent;import vn.svframe.svframelib.damage.DamageType;import vn.svframe.svframelib.player.resource.ResourceUpdateReason;import vn.svframe.svframelib.skill.SkillMetadata;import vn.svframe.svframelib.skill.handler.*;import vn.svframe.svframelib.skill.result.def.SimpleSkillResult;import vn.svframe.svframelib.util.EntityLocationType;import vn.svframe.svframelib.util.ParabolicProjectile;import vn.svframe.svframelib.util.configobject.ConfigObject;import vn.svframe.svframemmo.SVFrameMMO;import java.util.concurrent.ThreadLocalRandom;
@BuiltinSkillHandler(mods={"percent"},triggerable=false) public final class Ambers extends SkillHandler<SimpleSkillResult>{private static boolean hook;public Ambers(ConfigObject c){super(c);install();}private static synchronized void install(){if(hook)return;hook=true;PlayerAttackEvent.EVENT.register(e->{if(!e.getAttack().getDamage().hasType(DamageType.SKILL))return;var h=SVFrameLib.inst().getSkills().getHandler("AMBERS");if(h==null)return;var passive=e.getData().getPassiveSkillMap().getSkill(h);if(passive!=null)passive.getTriggeredSkill().cast(SkillMetadata.of(e));});}public SimpleSkillResult getResult(SkillMetadata m){return new SimpleSkillResult(m.hasAttackSource()&&m.getTargetLivingEntityOrNull()!=null);}public void whenCast(SimpleSkillResult r,SkillMetadata m){if(!r.isSuccessful())return;LivingEntity t=m.getTargetLivingEntityOrNull();if(!(t.getWorld() instanceof ServerWorld w))return;double a=ThreadLocalRandom.current().nextDouble(Math.PI*2);Vec3d pickup=t.getPos().add(4*Math.cos(a),0,4*Math.sin(a));var data=SVFrameMMO.playerData().get(m.getCaster().getData().getUniqueId());new ParabolicProjectile(w,EntityLocationType.BODY.getLocation(t),pickup,()->new AmberPickup(data,w,pickup,m.getParameter("percent")/100d).tick(),1,new DustParticleEffect(new Vector3f(1f,165f/255f,0f),1.3f));}
private record AmberPickup(vn.svframe.svframemmo.api.player.PlayerData data,ServerWorld world,Vec3d point,double percent){void tick(){tick(0);}void tick(int n){ServerPlayerEntity p=data.getPlayer();if(n>66||p==null||p.getWorld()==null)return;if(p.getWorld()!=world)return;if(p.getPos().add(0,1,0).squaredDistanceTo(point)<3){p.getWorld().playSound(null,p.getBlockPos(),SoundEvents.BLOCK_END_PORTAL_FRAME_FILL,SoundCategory.PLAYERS,1,1);double missing=data.getMaxResource(vn.svframe.svframemmo.api.player.profess.resource.PlayerResource.MANA)-data.getMana();data.giveMana(missing*percent,ResourceUpdateReason.SKILL);return;}world.spawnParticles(ParticleTypes.FLAME,point.x,point.y,point.z,5,.05,.05,.05,0);world.spawnParticles(new DustParticleEffect(new Vector3f(1f,165f/255f,0f),1.3f),point.x,point.y,point.z,1,0,0,0,0);vn.svframe.svframelib.fabric.SVFrameLibFabricMod.schedule(3,()->tick(n+1));}}}
